import{_ as o,o as a,c as t,a0 as s}from"./chunks/framework.C3yZ6M33.js";const u=JSON.parse('{"title":"Run a hub","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/run-a-hub.md","filePath":"how-to/run-a-hub.md"}'),d={name:"how-to/run-a-hub.md"};function i(n,e,h,r,c,l){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="run-a-hub" tabindex="-1">Run a hub <a class="header-anchor" href="#run-a-hub" aria-label="Permalink to &quot;Run a hub&quot;">​</a></h1><p>This guide shows how to run <code>peregrin-hub</code> — the headless aggregation gateway that merges nodes into one API and arbitrates entity/session ownership across the fleet.</p><h2 id="basics" tabindex="-1">Basics <a class="header-anchor" href="#basics" aria-label="Permalink to &quot;Basics&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_NODES</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;durable=http://127.0.0.1:18787@tok1;ci=http://10.0.0.5:18787@tok2&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_NODE_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">node token</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">peregrin-hub</span></span></code></pre></div><p><code>PEREGRIN_NODES</code> is <code>id=url[@token]</code> pairs, semicolon-separated — the <code>id</code> is how the hub names the node everywhere (entity rows, dispatch, <code>?node=</code> selectors). It maps onto Hypha&#39;s <code>HYPHA_NODES</code>; <code>peregrin-hub</code> reads only <code>PEREGRIN_NODES</code> (<code>HYPHA_NODES</code> applies to the standalone <code>hypha-hub</code> binary).</p><p>Binds <code>PEREGRIN_HUB_HOST:PEREGRIN_HUB_PORT</code> — default <code>127.0.0.1:13000</code> (<code>PEREGRIN_HUB_PORT</code> falls back to <code>PEREGRIN_PORT</code>). Non-loopback without <code>PEREGRIN_HUB_TOKEN</code> refuses to start.</p><h2 id="what-the-hub-does" tabindex="-1">What the hub does <a class="header-anchor" href="#what-the-hub-does" aria-label="Permalink to &quot;What the hub does&quot;">​</a></h2><ul><li><strong>Merges</strong> — the generic <code>/api/entities*</code> surface spans every configured node; <code>GET /api/node-status</code> reports per-node health.</li><li><strong>Routes</strong> — session ops go to the owning node; <code>hypha-control</code>&#39;s <code>pick_owner</code> resolves ownership when an entity is visible from multiple nodes.</li><li><strong>Arbitrates</strong> — the lock registry decides attach outcomes: free → read-write, held → read-only, stale holder → preempt, node down → queue via the durable outbox (<code>GET /api/pending-ops</code> shows its depth).</li><li><strong>Dispatches</strong> — hub-side fleet dispatch: a <code>kind=&quot;campaign&quot;</code> entity&#39;s <code>campaign.start</code> op is routed to a node whose <code>PEREGRIN_RUNNER_LABELS</code> satisfy the campaign&#39;s <code>runs_on</code> (durable nodes preferred over ephemeral, id tiebreak). See <a href="./../reference/fleet-runners.html">Fleet runners</a>.</li></ul><p>There is no bundled web UI on <code>main</code> — the hub serves the API only. The experimental Leptos UI lives on the <code>experimental/web</code> branch.</p><h2 id="auth-on-both-sides" tabindex="-1">Auth on both sides <a class="header-anchor" href="#auth-on-both-sides" aria-label="Permalink to &quot;Auth on both sides&quot;">​</a></h2><p>Two token hops exist and are independent:</p><ul><li>Client → hub: <code>PEREGRIN_HUB_TOKEN</code> (empty = open on loopback).</li><li>Hub → nodes: the per-node <code>@token</code> in <code>PEREGRIN_NODES</code>, sent as bearer; <code>PEREGRIN_NODE_TOKEN</code> seeds nodes listed without one.</li></ul><p><code>/api/pair</code> trades a one-time code minted on a node for a bearer credential (<code>sepia_…</code>), and <code>/api/auth/login</code>/<code>logout</code> run the cookie flow — <code>?access_token=</code> works only on the SSE paths.</p><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to &quot;Credentials&quot;">​</a></h2><p>Secrets sit behind <code>hypha-secret</code>, mapped through the <code>PEREGRIN_*</code> → <code>HYPHA_*</code> env boundary. <code>PEREGRIN_CREDENTIAL_STORE</code> accepts <code>auto</code> (default: OS keyring, file fallback), <code>keyring</code>, or <code>file</code> — the file store lives under the Hypha home (<code>$HYPHA_HOME/hub/credentials.json</code> or the mapped Peregrin home), not a <code>.env</code> dotenv backend.</p>`,15)])])}const b=o(d,[["render",i]]);export{u as __pageData,b as default};
